package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a claim of the sheet by id. */
public class LoadClaim {
    public void load(@Val Sheet sheet, @PathVariable("claimId") String claimId, ClaimRepository repository,
            Out<Claim> claimOut) throws ClaimNotFoundException {
        Long id;
        try {
            id = Long.valueOf(claimId.trim());
        } catch (NumberFormatException e) {
            throw new ClaimNotFoundException(claimId);
        }
        claimOut.set(repository.findByIdAndSheetId(id, sheet.getId())
                .orElseThrow(() -> new ClaimNotFoundException(claimId)));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, ClaimLogRepository log, ClaimCommentRepository comments, ClaimLineRepository lines,
            ObjectResponse<ClaimResponse> response) {
        response.send(ClaimResponse.from(claim, log.linesOf(claim), comments.linesOf(claim), lines.linesOf(claim)));
    }
}
package net.officefloor.hq.app.role;

import net.officefloor.hq.app.AuditUser;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;

/** The first step of every change: refuses it, before anything is read or written, when the signed-in name is a
 *  viewer on the sheet (a viewer sees everything and changes nothing). */
public class GuardViewer {
    public void guard(@PathVariable("sheetId") String sheetId,
            @RequestHeader(name = "X-User", required = false) String user, RoleRepository roles)
            throws ViewerRefusedException {
        if (Role.VIEWER.equals(roles.roleOf(sheetId, AuditUser.decode(user)))) {
            throw new ViewerRefusedException("A viewer cannot change anything on the sheet.");
        }
    }
}
# PUT /api/sheets/{sheetId}/claims/{claimId}/remind — remind an OPEN or PENDING claim, once per sheet's today.
guard:
  class: net.officefloor.hq.app.role.GuardViewer
  next: archived
archived:
  class: net.officefloor.hq.app.sheet.GuardArchived
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadOrCreateSheet
  govern: [ transaction ]
  next: claim
claim:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyRemind
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimReminded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the re-dating, once it is saved: the claim's line with its new date, then its old and new date. */
public class AuditClaimRedated {
    public void audit(@Parameter Redated redated, @Val Claim claim, PersonRepository people,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        String person = people.findById(claim.getPersonId()).map(Person::getName).orElse("");
        audit.record(ClaimAudit.line("CLAIM_REDATED", claim, person, AuditUser.decode(user))
                + " old=" + redated.oldDate() + " new=" + redated.newDate());
    }
}

