      <h2>Rates</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>To</th>
            <th>Rate (%)</th>
            <th>Versions</th>
            <th>In force today (%)</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.flatMap((g) => {
            const mine = (rates.data ?? []).filter((r) => r.sheet === sheet && r.grade === g);
